df = pd.DataFrame(rows, columns=["tenure", "score"])
pop = {"new": 0.5, "mid": 0.3, "long": 0.2}
r = poststratify(df, "tenure", "score", pop)
assert abs(r["raw_mean"] - 4.14) < 1e-12
assert abs(r["weighted_mean"] - 3.54) < 1e-12          # 0.5*3.0 + 0.3*3.8 + 0.2*4.5
assert {k: round(float(v), 6) for k, v in r["weights"].items()} == {"new": 5.0, "mid": 1.0, "long": 0.333333}
assert abs(r["kish_n"] - 174.4186046511628) < 1e-9     # 500 respondents behave like ~174

# if respondents already mirror the population, weights are all 1 and nothing changes
df2 = pd.DataFrame([("a", 2.0)] * 50 + [("b", 4.0)] * 50, columns=["g", "y"])
r2 = poststratify(df2, "g", "y", {"a": 0.5, "b": 0.5})
